CREATE TABLE orders(id int primary key, sku text, qty int);
CREATE TABLE outbox(id serial primary key, event_id uuid, event_type text, published boolean default false);
CREATE TABLE inbox(event_id uuid primary key);
CREATE TABLE inventory(sku text primary key, reserved int);
INSERT INTO inventory VALUES ('SKU-1', 100);

-- Step 1: producer — order + outbox in ONE transaction
BEGIN;
  INSERT INTO orders(id, sku, qty) VALUES (1, 'SKU-1', 10);
  INSERT INTO outbox(event_id, event_type)
    VALUES ('11111111-1111-1111-1111-111111111111', 'order.created');
COMMIT;

-- Step 2: consumer — relay delivers the SAME event_id twice.
-- First delivery: claim the event_id, then apply the business effect.
WITH claim AS (
  INSERT INTO inbox(event_id) VALUES ('11111111-1111-1111-1111-111111111111')
  ON CONFLICT (event_id) DO NOTHING
  RETURNING event_id
)
UPDATE inventory SET reserved = reserved + 10
WHERE sku = 'SKU-1' AND EXISTS (SELECT 1 FROM claim);

-- Second (duplicate) delivery: same event_id. The claim conflicts → 0 rows → no decrement.
WITH claim AS (
  INSERT INTO inbox(event_id) VALUES ('11111111-1111-1111-1111-111111111111')
  ON CONFLICT (event_id) DO NOTHING
  RETURNING event_id
)
UPDATE inventory SET reserved = reserved + 10
WHERE sku = 'SKU-1' AND EXISTS (SELECT 1 FROM claim);
